@startuml

class Person {
  + personId : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorRole {
  + position : int
}

class ReviewerRole {}

Person "1" -- "1" ResearchInstitution : worksFor

ScientificArticle "1" -- "1..*" AuthorRole
AuthorRole "1" -- "1" Person

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

PeerReviewedPaper "1" -- "1..*" ReviewerRole
ReviewerRole "1" -- "1" Person

TechnicalReport "*" -- "1" ResearchInstitution : publishedBy

Publisher "1" -- "1..*" Journal
ResearchInstitution "0..*" -- "0..*" Journal : subscribesTo

PeerReviewedPaper "*" -- "1" Journal : publishedIn

@enduml

